import React, { useRef } from 'react';

// ─── Brand tokens ─────────────────────────────────────────────────────────────
const BLUE   = '#009FE3';
const NAVY   = '#003D6B';

// ─── Types ───────────────────────────────────────────────────────────────────

export interface FilterDef {
  /** Unique key used in state maps */
  id: string;
  /** Human-readable label shown on the card */
  label: string;
  /**
   * Must match the ThoughtSpot column name exactly (case-sensitive).
   * Update these to match the Smyths data model.
   */
  columnName: string;
  /** Selectable values — populated live from the ThoughtSpot REST API */
  options: string[];
}

export type FilterSelection = Record<string, string[]>;

interface FilterBarProps {
  filters: FilterDef[];
  selected: FilterSelection;
  onSelectionChange: (filterId: string, values: string[]) => void;
  onClearAll: () => void;
  /** True while live dimension values are still being fetched */
  loading?: boolean;
  /**
   * Measure data per filter: filterId → { dimensionValue → measureValue }
   * When provided, each filter card shows the measure next to each option.
   */
  measureData?: Record<string, Record<string, number>>;
  /** Human-readable label for the measure shown (e.g. "Net Revenue") */
  measureLabel?: string;
  /** True while measure data is being fetched */
  measuresLoading?: boolean;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Compact number formatter — renders as K / M to keep the card narrow.
 * e.g. 1_234_567 → "1.2M"  |  45_900 → "46K"  |  312 → "312"
 */
function fmtMeasure(n: number): string {
  if (Math.abs(n) >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (Math.abs(n) >= 1_000)     return `${Math.round(n / 1_000)}K`;
  return Math.round(n).toLocaleString();
}

// ─── Single filter card ───────────────────────────────────────────────────────

function FilterCard({
  filter,
  selected,
  onChange,
  measureValues,
  measureLabel,
  measuresLoading,
}: {
  filter: FilterDef;
  selected: string[];
  onChange: (values: string[]) => void;
  measureValues?: Record<string, number>;
  measureLabel?: string;
  measuresLoading?: boolean;
}) {
  const hasSelection  = selected.length > 0;
  const hasMeasures   = !!measureValues && Object.keys(measureValues).length > 0;
  const listRef       = useRef<HTMLDivElement>(null);

  // Sort options by measure descending when data is available; else alphabetical
  const sortedOptions = hasMeasures
    ? [...filter.options].sort(
        (a, b) => (measureValues![b] ?? 0) - (measureValues![a] ?? 0)
      )
    : filter.options;

  const maxMeasure = hasMeasures
    ? Math.max(...Object.values(measureValues!), 1)
    : 1;

  const toggle = (option: string) => {
    if (selected.includes(option)) {
      onChange(selected.filter((v) => v !== option));
    } else {
      onChange([...selected, option]);
    }
  };

  // Card is wider when showing measures
  const cardWidth = hasMeasures ? 240 : 196;

  return (
    <div
      style={{
        width: cardWidth,
        flexShrink: 0,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#FFFFFF',
        borderRadius: 10,
        border: `1.5px solid ${hasSelection ? BLUE : 'rgba(0,0,0,0.09)'}`,
        boxShadow: hasSelection
          ? `0 0 0 3px rgba(0,159,227,0.12), 0 2px 8px rgba(0,0,0,0.06)`
          : '0 1px 4px rgba(0,0,0,0.06)',
        overflow: 'hidden',
        transition: 'border-color 0.15s ease, box-shadow 0.15s ease',
      }}
    >
      {/* ── Card header ── */}
      <div
        style={{
          padding: '9px 12px 8px',
          borderBottom: '1px solid rgba(0,0,0,0.07)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          flexShrink: 0,
          background: hasSelection
            ? `linear-gradient(135deg, rgba(0,159,227,0.08) 0%, rgba(0,159,227,0.03) 100%)`
            : '#FAFAFA',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {/* Filter funnel icon */}
          <svg width="11" height="11" viewBox="0 0 24 24" fill="none"
            stroke={hasSelection ? BLUE : 'rgba(0,0,0,0.35)'}
            strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3" />
          </svg>
          <span style={{ fontSize: 12, fontWeight: 700, color: hasSelection ? BLUE : NAVY, letterSpacing: '-0.01em' }}>
            {filter.label}
          </span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {/* Measure label pill — shown when measure data available */}
          {hasMeasures && measureLabel && (
            <span style={{
              fontSize: 9,
              fontWeight: 600,
              color: 'rgba(0,61,107,0.55)',
              backgroundColor: 'rgba(0,61,107,0.07)',
              borderRadius: 4,
              padding: '1px 5px',
              letterSpacing: '0.03em',
              textTransform: 'uppercase',
              whiteSpace: 'nowrap',
            }}>
              {measureLabel}
            </span>
          )}
          {/* Spinner while measures are loading */}
          {measuresLoading && !hasMeasures && (
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none"
              stroke={BLUE} strokeWidth="2.5" strokeLinecap="round"
              style={{ animation: 'ts-spin 0.8s linear infinite', flexShrink: 0 }}>
              <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
            </svg>
          )}
          {hasSelection && (
            <button type="button" onClick={() => onChange([])}
              style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 10,
                color: BLUE, fontWeight: 700, padding: '1px 5px', borderRadius: 4,
                letterSpacing: '0.02em', lineHeight: 1.4 }}>
              Clear
            </button>
          )}
        </div>
      </div>

      {/* ── Scrollable options list ── */}
      <div
        ref={listRef}
        style={{
          overflowY: 'auto',
          maxHeight: 200,
          padding: '3px 0',
          scrollbarWidth: 'thin',
          scrollbarColor: `rgba(0,159,227,0.3) transparent`,
        }}
      >
        {filter.options.length === 0 && (
          // Skeleton shimmer while dimension values load
          <div style={{ padding: '8px 12px', display: 'flex', flexDirection: 'column', gap: 7 }}>
            {[70, 55, 80, 60, 75].map((w, i) => (
              <div key={i} style={{ height: 10, width: `${w}%`, borderRadius: 4,
                background: 'linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%)',
                backgroundSize: '200% 100%', animation: 'ts-shimmer 1.4s ease infinite' }} />
            ))}
            <style>{`@keyframes ts-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }`}</style>
          </div>
        )}

        {/* ── "All" synthetic first option — clears the filter ── */}
        {filter.options.length > 0 && (
          <label
            style={{
              display: 'flex', alignItems: 'center', gap: 8,
              padding: '5px 12px', cursor: 'pointer',
              backgroundColor: !hasSelection ? 'rgba(0,159,227,0.07)' : 'transparent',
              borderBottom: '1px solid rgba(0,0,0,0.05)',
              userSelect: 'none',
            }}
            onMouseEnter={(e) => {
              if (hasSelection) (e.currentTarget as HTMLElement).style.backgroundColor = 'rgba(0,0,0,0.03)';
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLElement).style.backgroundColor =
                !hasSelection ? 'rgba(0,159,227,0.07)' : 'transparent';
            }}
          >
            <span style={{
              width: 15, height: 15, borderRadius: 3, flexShrink: 0,
              border: `1.5px solid ${!hasSelection ? BLUE : 'rgba(0,0,0,0.22)'}`,
              backgroundColor: !hasSelection ? BLUE : '#FFFFFF',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              transition: 'all 0.10s ease',
            }}>
              {!hasSelection && (
                <svg width="9" height="7" viewBox="0 0 9 7" fill="none">
                  <path d="M1 3.5L3.5 6L8 1" stroke="white" strokeWidth="1.6"
                    strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              )}
            </span>
            <input type="checkbox" checked={!hasSelection} onChange={() => onChange([])}
              style={{ display: 'none' }} />
            <span style={{
              fontSize: 12.5, color: !hasSelection ? BLUE : '#2a2a2a',
              fontWeight: !hasSelection ? 700 : 500,
              letterSpacing: '-0.01em', fontStyle: 'italic',
            }}>
              All
            </span>
          </label>
        )}

        {/* ── Actual dimension options ── */}
        {sortedOptions.map((option) => {
          const isSelected   = selected.includes(option);
          const rawMeasure   = hasMeasures ? (measureValues![option] ?? 0) : null;
          const barPct       = hasMeasures ? ((rawMeasure! / maxMeasure) * 100) : 0;

          return (
            <label
              key={option}
              style={{
                position: 'relative',
                display: 'flex',
                alignItems: 'center',
                gap: 8,
                padding: '5px 10px 5px 12px',
                cursor: 'pointer',
                backgroundColor: isSelected ? 'rgba(0,159,227,0.07)' : 'transparent',
                transition: 'background-color 0.10s ease',
                userSelect: 'none',
              }}
              onMouseEnter={(e) => {
                if (!isSelected)
                  (e.currentTarget as HTMLElement).style.backgroundColor = 'rgba(0,0,0,0.03)';
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLElement).style.backgroundColor =
                  isSelected ? 'rgba(0,159,227,0.07)' : 'transparent';
              }}
            >
              {/* Proportional measure bar behind the row */}
              {hasMeasures && barPct > 0 && (
                <div style={{
                  position: 'absolute',
                  left: 0, top: 0, bottom: 0,
                  width: `${barPct}%`,
                  backgroundColor: isSelected
                    ? 'rgba(0,159,227,0.14)'
                    : 'rgba(0,61,107,0.05)',
                  borderRight: `2px solid ${isSelected ? 'rgba(0,159,227,0.35)' : 'rgba(0,61,107,0.12)'}`,
                  transition: 'width 0.3s ease',
                  pointerEvents: 'none',
                }} />
              )}

              {/* Custom checkbox */}
              <span style={{
                width: 15, height: 15, borderRadius: 3, flexShrink: 0,
                border: `1.5px solid ${isSelected ? BLUE : 'rgba(0,0,0,0.22)'}`,
                backgroundColor: isSelected ? BLUE : '#FFFFFF',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                transition: 'all 0.10s ease',
                position: 'relative', zIndex: 1,
              }}>
                {isSelected && (
                  <svg width="9" height="7" viewBox="0 0 9 7" fill="none">
                    <path d="M1 3.5L3.5 6L8 1" stroke="white" strokeWidth="1.6"
                      strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                )}
              </span>
              <input type="checkbox" checked={isSelected} onChange={() => toggle(option)}
                style={{ display: 'none' }} />

              {/* Dimension label */}
              <span style={{
                fontSize: 12.5,
                color: isSelected ? BLUE : '#2a2a2a',
                fontWeight: isSelected ? 600 : 400,
                letterSpacing: '-0.01em',
                lineHeight: 1.3,
                flex: 1,
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                position: 'relative', zIndex: 1,
              }}>
                {option}
              </span>

              {/* Measure value — right-aligned */}
              {rawMeasure !== null && (
                <span style={{
                  fontSize: 11,
                  fontWeight: 600,
                  color: isSelected ? BLUE : 'rgba(0,61,107,0.60)',
                  letterSpacing: '-0.02em',
                  whiteSpace: 'nowrap',
                  flexShrink: 0,
                  position: 'relative', zIndex: 1,
                }}>
                  {fmtMeasure(rawMeasure)}
                </span>
              )}
            </label>
          );
        })}
      </div>

      {/* ── Selection count footer ── */}
      {hasSelection && (
        <div style={{
          padding: '5px 12px',
          borderTop: '1px solid rgba(0,159,227,0.10)',
          backgroundColor: 'rgba(0,159,227,0.04)',
          flexShrink: 0,
          display: 'flex', alignItems: 'center', gap: 5,
        }}>
          <svg width="10" height="10" viewBox="0 0 24 24" fill={BLUE}>
            <circle cx="12" cy="12" r="10" />
            <path d="M8 12l3 3 5-6" stroke="white" strokeWidth="2"
              strokeLinecap="round" strokeLinejoin="round" fill="none" />
          </svg>
          <span style={{ fontSize: 11, color: BLUE, fontWeight: 600 }}>
            {selected.length} of {filter.options.length} selected
          </span>
        </div>
      )}

      <style>{`
        @keyframes ts-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes ts-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
      `}</style>
    </div>
  );
}

// ─── Filter bar ───────────────────────────────────────────────────────────────

export default function FilterBar({
  filters,
  selected,
  onSelectionChange,
  onClearAll,
  loading = false,
  measureData,
  measureLabel,
  measuresLoading = false,
}: FilterBarProps) {
  const totalSelected = Object.values(selected).reduce((sum, v) => sum + v.length, 0);

  return (
    <div style={{
      padding: '0 2.5rem 1.25rem',
      borderBottom: '1px solid rgba(0,0,0,0.06)',
      marginBottom: '1rem',
    }}>
      {/* ── Bar header ── */}
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        marginBottom: 10,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none"
            stroke={NAVY} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
            <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3" />
          </svg>
          <span style={{ fontSize: 12, fontWeight: 700, color: NAVY, letterSpacing: '-0.01em' }}>
            Filters
          </span>
          {totalSelected > 0 && (
            <span style={{
              fontSize: 10, fontWeight: 700, backgroundColor: BLUE, color: '#FFFFFF',
              borderRadius: 10, padding: '1px 7px', letterSpacing: '0.02em',
            }}>
              {totalSelected} active
            </span>
          )}
          {/* Loading spinner for dimension values */}
          {loading && (
            <span style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 10, color: 'rgba(0,0,0,0.35)', fontWeight: 500 }}>
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke={BLUE}
                strokeWidth="2.5" strokeLinecap="round"
                style={{ animation: 'ts-spin 0.8s linear infinite' }}>
                <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
              </svg>
              Loading values…
            </span>
          )}
          {/* Spinner for measure data */}
          {measuresLoading && !loading && (
            <span style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 10, color: 'rgba(0,0,0,0.35)', fontWeight: 500 }}>
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke={BLUE}
                strokeWidth="2.5" strokeLinecap="round"
                style={{ animation: 'ts-spin 0.8s linear infinite' }}>
                <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
              </svg>
              Loading {measureLabel ?? 'measures'}…
            </span>
          )}
        </div>

        {totalSelected > 0 && (
          <button type="button" onClick={onClearAll}
            style={{
              background: 'none', border: 'none', cursor: 'pointer',
              fontSize: 12, color: 'rgba(0,0,0,0.40)', fontWeight: 500,
              padding: 0, letterSpacing: '-0.01em',
            }}>
            Clear all filters
          </button>
        )}
      </div>

      {/* ── Horizontally scrollable card row ── */}
      <div style={{
        display: 'flex', gap: 10, overflowX: 'auto', paddingBottom: 6,
        scrollbarWidth: 'thin',
        scrollbarColor: `rgba(0,159,227,0.25) transparent`,
      }}>
        {filters.map((f) => (
          <FilterCard
            key={f.id}
            filter={f}
            selected={selected[f.id] ?? []}
            onChange={(values) => onSelectionChange(f.id, values)}
            measureValues={measureData?.[f.id]}
            measureLabel={measureLabel}
            measuresLoading={measuresLoading}
          />
        ))}
      </div>
    </div>
  );
}
